from pathlib import Path
import json,hashlib,html,datetime,os,xml.etree.ElementTree as ET
p=Path('docs/validation/background-103');features=json.loads((p/'features.json').read_text());out={}
notes={45:('공유 클립보드 보호','별도 Window Station 생성 두 번 모두 Win32 5로 실패했습니다. 실제 붙여넣기·서식 Undo는 실행하지 않았습니다.','window-station-isolation-attempts.json'),48:('공유 클립보드 보호','실제 clipboard history 선택·붙여넣기는 공유 WinSta0 클립보드를 바꾸므로 실행하지 않았습니다.','window-station-isolation-attempts.json'),66:('실제 인쇄 출력 미수집','프린터 또는 PDF 드라이버에 실제 출력하지 않았습니다. 편집기 색상 관찰을 인쇄 색상 검증으로 세지 않습니다.',None),70:('원본 렌더링 관측 한계','실제 Build Output에서 CA 파일 경로 분류는 관찰했지만 VA 네이티브 강조를 유효하게 포착하지 못했습니다. top-level PrintWindow의 오래된 이미지는 기각했습니다.','output-highlight.remaining.json'),71:('원본 렌더링 관측 한계','동일 문서·커서 A-B-A에서 CA 두 괄호 강조는 관찰했습니다. VA 네이티브 강조는 양성 대조를 확보하지 못해 제품 실패로 단정하지 않았습니다.','brace-visual.geometry.json'),72:('원본 렌더링 관측 한계','불균형 괄호의 CA 강조와 원상복귀는 포착했지만 VA 양성 대조가 없습니다.','brace-visual.geometry.json'),75:('원본 양성 대조 미확보','IDE squiggle을 끄고 실제 문자 입력 후 기다렸습니다. CA 오류 1개, VA 0개였지만 VA 기능의 올바른 작동 조건을 충분히 입증하지 못해 판정하지 않았습니다.','unknown-symbol.transaction.json'),99:('기본 브라우저 재사용 방지','실제 URL 생성·플러그인 계약은 시험했지만 Shell launch는 기존 사용자 브라우저를 재사용할 수 있어 실행하지 않았습니다.','VA.issue-links.bundle.json'),102:('부분 확인','옵션 페이지는 대조했습니다. 사용자 확장자 매핑까지 포함한 VA/CA 파싱·무시·재열기 동작은 실행 검증을 마치지 못했습니다.','options-pages/VA-Projects_and_Files.json'),103:('배정 조회만 확인','현재 VA 명령 후보 19개와 CA 22개 배정을 조회했습니다. 기존 키 보존·충돌·전체 물리 키 동작은 미검증입니다. 이전 버전 물리 입력 기록을 이번 검증으로 재사용하지 않았습니다.','VA.shortcut-bindings.current.json'),104:('입력 경로 양성 대조 미확보','Ctrl/Alt 클릭 창 메시지를 정확한 편집기 좌표로 보냈으나 양쪽 모두 이동하지 않았습니다. 이 결과는 자동화 경로 미확인으로 기록하고 제품 실패로 세지 않았습니다.','VA.mouse-alt-root.actual.json'),107:('설정 저장 확인 / 실제 동시 파싱 미확인','양쪽 설정 1 저장·재열기·복원을 확인했습니다. 스레드 시작 주소도 조사했지만 실제 parser worker를 식별하지 못했습니다. Native worker 개수를 parser concurrency로 추측하지 않았습니다.','parse-threads.transaction.json')}
notes={n:v for n,v in notes.items() if next(x for x in features if x['id']=='VA-F%03d'%n)['state']=='unverified'}
for n,(stage,reason,ev) in notes.items():
 row=next(x for x in features if x['id']=='VA-F%03d'%n);assert row['state']=='unverified';value=dict(id=row['id'],name=row['name'],stage=stage,reason=reason,passed=False)
 if ev:
  f=p/ev;assert f.exists();value['evidence']=dict(file=ev,sha256=hashlib.sha256(f.read_bytes()).hexdigest())
 out[row['id']]=value
assert len(out)==sum(x['state']=='unverified' for x in features)==len(notes)
(p/'remaining-limitations.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
state=Path(os.environ['LOCALAPPDATA'])/'CodeAssist/startup.xml';tree=ET.parse(state);root=tree.getroot();values={x.tag:x.text for x in root.iter() if x.tag in ['StepFilterEnabled','StepFilterPatterns']};assert values=={'StepFilterEnabled':'false','StepFilterPatterns':'std::*'},values
cleanup=dict(stepFilter=values,caRootCompileFlagsAbsent=not Path('.local/parity-runs/background-103/CA/compile_flags.txt').exists(),settingsReadbackFiles=json.loads((p/'final-settings.readbacks.json').read_text()))
assert cleanup['caRootCompileFlagsAbsent'];(p/'final-cleanup-settings.json').write_text(json.dumps(cleanup,ensure_ascii=False,indent=2),encoding='utf-8')
rows=''
for r in features:
 evidence=r.get('mainEvidence') or 'background-103/remaining-limitations.json';link=(evidence if isinstance(evidence,str) else 'background-103/adjudicated.json').removeprefix('background-103/')
 reason=out[r['id']]['reason'] if r['id'] in out else r['reason'];rows+='<tr><td>'+r['id']+'</td><td>'+html.escape(r['name'])+'</td><td>'+html.escape(r['state'])+'</td><td>'+html.escape(reason)+'</td><td><a href="'+html.escape(link,quote=True)+'">증거</a></td></tr>'
counts={s:sum(r['state']==s for r in features) for s in ['representative-match','different','unverified']}
text='''<!doctype html><meta charset="utf-8"><title>108항목 검증 현황</title><style>body{background:#181a20;color:#e5e7eb;font:15px Segoe UI,sans-serif;margin:28px}h1,h2{color:#ffd346}a{color:#83c4ff}table{border-collapse:collapse;width:100%}td,th{padding:10px;border:1px solid #444;vertical-align:top}p{line-height:1.7}.notice{border-left:4px solid #ffd346;padding:14px;background:#252832}</style><h1>108항목 검증 현황</h1><p class="notice"><b>판정 확보 {determinate}/108 = {rate}%</b><br>대표 시나리오 엄격 일치 {matched}개 · 차이 {different}개 · 미판정 {unverified}개.<br>누적 대표 판정이며 이번 회차 전체 신규 재실행 완료나 기능 전체 인증이 아닙니다. 차이는 서식·커서·UI 차이와 실제 동작 결함을 모두 포함하며 전체 제품 동기화율로 환산하지 않습니다.</p><p>초기 분리 데스크톱 기록과 이후 사용자 승인하에 수행한 실제 키·마우스·브라우저 검증을 합친 누적 자료입니다. Microsoft Print to PDF 출력도 실제 수집했습니다.</p><p><a href="index.html">판정별 실행 결과·컴파일·이미지 대조</a> · <a href="options-pages/index.html">전체 옵션 페이지 이미지</a> · <a href="remaining-limitations.json">남은 {unverified}항목의 한계와 근거 해시</a> · <a href="final-cleanup-settings.json">설정 복원 확인</a></p><p><a href="../full-108-107/index.html">이번 미판정 해소 실행 증거·PDF 대조</a> · <a href="../fixes-104/index.html">0.0.95 생성 코드 수정 검증</a></p><h2>0.0.94 실행에서 확인한 결함 (아래 생성 코드 5건은 0.0.95에서 수정, 별도 보고서 참조)</h2><ul><li>F018 setter 생성: value=value가 되어 실행값 불일치</li><li>F029 Add Member: 클래스 밖 생성으로 멤버 접근 컴파일 실패</li><li>F035 Create Declaration: 잘못된 선언 위치로 컴파일 실패</li><li>F038 헤더 구현 생성: non-inline 정의의 다중 번역 단위 링크 실패</li><li>F041 클래스 이름 삽입: 생성 문장 컴파일 실패</li><li>F074 철자 밑줄: 원본 오류 2개 / CA 0개</li></ul><h2>전체 108항목</h2><table><tr><th>ID</th><th>기능</th><th>판정</th><th>범위·실제 관찰</th><th>근거</th></tr>'''+rows+'</table>'
text=text.replace('{determinate}',str(108-counts['unverified'])).replace('{rate}',f"{(108-counts['unverified'])/108*100:.2f}").replace('{matched}',str(counts['representative-match'])).replace('{different}',str(counts['different'])).replace('{unverified}',str(counts['unverified']))
(p/'status.html').write_text(text,encoding='utf-8')
print(counts,'remaining evidence + settings restoration validated')
